def validate_isbn10(code: str) -> bool:
    # Remove hyphens and spaces
    cleaned = code.replace("-", "").replace(" ", "")

    # Check length
    if len(cleaned) != 10:
        return False

    # Check first 9 characters are digits
    if not cleaned[:9].isdigit():
        return False

    # Check 10th character is a digit or X/x
    if not (cleaned[9].isdigit() or cleaned[9].upper() == 'X'):
        return False

    # Calculate the total
    total = 0
    for i in range(10):
        if cleaned[i].upper() == 'X':
            value = 10
        else:
            value = int(cleaned[i])
        total += value * (10 - i)

    # Check divisibility by 11
    return total % 11 == 0

