def format_bytes(count: int) -> str:
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    if count == 0:
        return f"0 B"

    for i, unit in enumerate(units):
        if i > 0 and count < 1024:
            break
        if i == len(units) - 1 or (count // 1024) < 1:
            value = count / (1024 ** i)
            if unit == 'B':
                return f"{int(value)} {unit}"
            else:
                return f"{value:.1f} {unit}"
        count = count // 1024
    return f"{count} TB"

